// constants/exerciseCatalog.ts — GainQuest's exercise library: every exercise from
// free-exercise-db (github.com/yuhonas/free-exercise-db, public domain), with photos.
// Data files are generated by a build script: exerciseCatalog.json, exerciseImages.ts,
// legacyExerciseNames.ts.
import { ImageSourcePropType } from 'react-native';
import RAW_CATALOG from './exerciseCatalog.json';
import { EXERCISE_IMAGES } from './exerciseImages';
import { LEGACY_EXERCISE_NAMES } from './legacyExerciseNames';
import { makeCanonicalizer, EXERCISE_ALIASES } from '../utils/exerciseNames';

export interface CatalogExercise {
  name: string;
  group: string;            // Chest | Back | Shoulders | Biceps | Triceps | Legs | Core | Forearms
  pattern: string;          // movement type, e.g. 'Presses', 'Rows', 'Stretches'
  category: string;         // Strength | Stretching | Plyometrics | Cardio | ...
  equipment: string | null;
  level: string;
  primary: string[];
  secondary: string[];
  steps: string[];
  images: ImageSourcePropType[];
}

type RawExercise = { n: string; g: string; p: string; c: string; e: string | null; l: string; pm: string[]; sm: string[]; s: string[] };

export const EXERCISE_CATALOG: CatalogExercise[] = (RAW_CATALOG as RawExercise[]).map((r, i) => ({
  name: r.n, group: r.g, pattern: r.p, category: r.c, equipment: r.e, level: r.l,
  primary: r.pm, secondary: r.sm, steps: r.s, images: EXERCISE_IMAGES[i],
}));

export const MUSCLE_GROUP_ORDER = ['Chest', 'Back', 'Shoulders', 'Biceps', 'Triceps', 'Legs', 'Core', 'Forearms'];

const BY_NAME = new Map(EXERCISE_CATALOG.map(e => [e.name, e]));

// Old app names ("Bench Press") and everyday spellings ("pushdown") → catalog names
const ALIASES: Record<string, string> = { ...LEGACY_EXERCISE_NAMES };
for (const [alias, oldName] of Object.entries(EXERCISE_ALIASES)) {
  ALIASES[alias] = LEGACY_EXERCISE_NAMES[oldName] ?? oldName;
}
const toCatalogName = makeCanonicalizer(EXERCISE_CATALOG.map(e => e.name), ALIASES);

/** The catalog name for any spelling of an exercise, or null if it isn't in the catalog. */
export function catalogName(name: string): string | null {
  return toCatalogName(name);
}

/** Full catalog entry (photos, steps, muscles...) for any spelling of an exercise. */
export function findExercise(name: string): CatalogExercise | undefined {
  const n = toCatalogName(name);
  return n ? BY_NAME.get(n) : undefined;
}

/** Muscle group → exercise names, grouped by movement type then A–Z. */
export const EXERCISE_LIBRARY: Record<string, string[]> = Object.fromEntries(
  MUSCLE_GROUP_ORDER.map(g => [
    g,
    EXERCISE_CATALOG
      .filter(e => e.group === g)
      .sort((a, b) => a.pattern.localeCompare(b.pattern) || a.name.localeCompare(b.name))
      .map(e => e.name),
  ])
);

// Bodyweight moves are logged by reps, not weight
const LEGACY_BODYWEIGHT = [
  'Pull Up', 'Chin Up', 'Muscle Up', 'Chest Dip', 'Tricep Dip', 'Push Up', 'Diamond Push Up',
  'Sit Up', 'Crunch', 'Leg Raise', 'Hanging Leg Raise',
].map(n => LEGACY_EXERCISE_NAMES[n]).filter(Boolean);

export const BODYWEIGHT_EXERCISES: string[] = [...new Set([
  ...EXERCISE_CATALOG
    .filter(e => e.equipment === 'Body only' && (e.category === 'Strength' || e.category === 'Plyometrics'))
    .map(e => e.name),
  ...LEGACY_BODYWEIGHT,
])];
